import json
import os

class Tugas:
    def __init__(self, judul, selesai=False):
        self.judul = judul
        self.selesai = selesai

    def __str__(self):
        tanda = "x" if self.selesai else " "
        return f"[{tanda}] {self.judul}"

class DaftarTugas:
    def __init__(self):
        self.isi = []

    def tambah(self, judul):
        if not judul.strip():
            raise ValueError("Judul tidak boleh kosong")
        self.isi.append(Tugas(judul.strip()))

    def ambil(self, nomor):
        if not nomor.isdigit() or not 1 <= int(nomor) <= len(self.isi):
            raise ValueError("Nomor tidak ada")
        return self.isi[int(nomor) - 1]

    def tandai(self, nomor):
        self.ambil(nomor).selesai = True

    def hapus(self, nomor):
        self.isi.remove(self.ambil(nomor))

    def lihat(self):
        if not self.isi:
            return "Belum ada tugas"
        return "\n".join(f"{no}. {t}" for no, t in enumerate(self.isi, start=1))

    def simpan(self, nama_file):
        data = [{"judul": t.judul, "selesai": t.selesai} for t in self.isi]
        with open(nama_file, "w") as f:
            json.dump(data, f)

    def muat(self, nama_file):
        if not os.path.exists(nama_file):
            return
        with open(nama_file) as f:
            data = json.load(f)
        self.isi = [Tugas(d["judul"], d["selesai"]) for d in data]

    def cari(self, kata):
        hasil = [f"{no}. {t}" for no, t in enumerate(self.isi, start=1) if kata.lower() in t.judul.lower()]
        return "\n".join(hasil) if hasil else "Tidak ditemukan"

    def ringkas(self):
        selesai = sum(1 for t in self.isi if t.selesai)
        return f"{len(self.isi)} tugas, {selesai} selesai, {len(self.isi) - selesai} belum"

def baca_perintah(baris):
    bagian = baris.strip().split(" ", 1)
    return bagian[0], (bagian[1] if len(bagian) > 1 else "")

def jalankan(daftar):
    while True:
        perintah, sisa = baca_perintah(input())
        if perintah == "keluar":
            break
        try:
            if perintah == "tambah":
                daftar.tambah(sisa)
            elif perintah == "lihat":
                print(daftar.lihat())
            elif perintah == "selesai":
                daftar.tandai(sisa)
            elif perintah == "hapus":
                daftar.hapus(sisa)
            elif perintah == "cari":
                print(daftar.cari(sisa))
            elif perintah == "ringkas":
                print(daftar.ringkas())
            else:
                print("Perintah tidak dikenal")
        except ValueError as e:
            print("Gagal:", e)

FILE = "tugas.json"
if os.path.exists(FILE):
    os.remove(FILE)          # mulai bersih untuk pengujian

d = DaftarTugas()
d.muat(FILE)
jalankan(d)
d.simpan(FILE)
